    h, w = len(grid), len(grid[0])
    # Grid is partitioned by full 8 lines into 3x3 (or generally) cells.
    rs = [i for i in range(h) if all(x == 8 for x in grid[i])]
    cs = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]
    rb = [-1] + rs + [h]
    cb = [-1] + cs + [w]
    out = [row[:] for row in grid]
    markers = {}
    for ri in range(len(rb)-1):
        for ci in range(len(cb)-1):
            r0, r1 = rb[ri]+1, rb[ri+1]
            c0, c1 = cb[ci]+1, cb[ci+1]
            vals = [(grid[r][c], r, c) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] not in (0,8)]
            if vals: markers[(ri,ci)] = vals[0][0]
    # Each marker color paints the entire row/column of regions aligned with it;
    # if opposing markers occur on a row, their region rows take each one's color by column reflection.
    # Identify isolated non-background marker rows/cols and expand to full regions.
    for (ri,ci), color in markers.items():
        r0,r1=rb[ri]+1,rb[ri+1]
        c0,c1=cb[ci]+1,cb[ci+1]
        for r in range(r0,r1):
            for c in range(c0,c1): out[r][c]=color
    # In observed example, paired 3s across a region row fill all regions in that row with 3,
    # while 2 marker columns fill their entire region columns with 2; intersections resolve to 6.
    marked_rows = {ri for ri,ci in markers if markers[(ri,ci)]==3}
    marked_cols = {ci for ri,ci in markers if markers[(ri,ci)]==2}
    for ri in marked_rows:
        for ci in range(len(cb)-1):
            for r in range(rb[ri]+1,rb[ri+1]):
                for c in range(cb[ci]+1,cb[ci+1]): out[r][c]=3
    for ci in marked_cols:
        for ri in range(len(rb)-1):
            for r in range(rb[ri]+1,rb[ri+1]):
                for c in range(cb[ci]+1,cb[ci+1]): out[r][c]=2
    for ri in marked_rows:
        for ci in marked_cols:
            for r in range(rb[ri]+1,rb[ri+1]):
                for c in range(cb[ci]+1,cb[ci+1]): out[r][c]=6
    return out
