def transform(grid):
    h,w=len(grid),len(grid[0])
    rs=[r for r in range(h) if all(v==8 for v in grid[r])]
    cs=[c for c in range(w) if all(grid[r][c]==8 for r in range(h))]
    rb=[-1]+rs+[h]; cb=[-1]+cs+[w]
    nr,nc=len(rb)-1,len(cb)-1
    pts={}
    for i in range(nr):
        for j in range(nc):
            for r in range(rb[i]+1,rb[i+1]):
                for c in range(cb[j]+1,cb[j+1]):
                    if grid[r][c] not in (0,8): pts.setdefault(grid[r][c],[]).append((i,j))
    out=[row[:] for row in grid]
    # For each color, connect its marker centers with horizontal/vertical strokes
    # spanning the extrema along each aligned row or column.
    strokes={}
    for color, p in pts.items():
        rows=set(); cols=set()
        for i in set(x for x,y in p):
            js=[y for x,y in p if x==i]
            if len(js)>=2: rows.update((i,j) for j in range(min(js),max(js)+1))
        for j in set(y for x,y in p):
            is_=[x for x,y in p if y==j]
            if len(is_)>=2: cols.update((i,j) for i in range(min(is_),max(is_)+1))
        strokes[color]=rows|cols
    for color,cells in strokes.items():
        for i,j in cells:
            for r in range(rb[i]+1,rb[i+1]):
                for c in range(cb[j]+1,cb[j+1]):
                    if grid[r][c]!=8: out[r][c]=color
    for i in range(nr):
        for j in range(nc):
            colors={color for color,cells in strokes.items() if (i,j) in cells}
            if len(colors)>1:
                for r in range(rb[i]+1,rb[i+1]):
                    for c in range(cb[j]+1,cb[j+1]): out[r][c]=6
    return out
